const [open, setOpen] = useState(false);

<Popup
  open={open}
  onOpenChange={setOpen}
  role="menu"
  content={
    <>
      <button type="button" role="menuitem">Rename</button>
      <button type="button" role="menuitem">Delete</button>
    </>
  }
>
  <Button onClick={() => setOpen((current) => !current)}>Actions</Button>
</Popup>

const [open, setOpen] = useState(false);

async function handleSave() {
  await save();
  setOpen(true);
}

<Popup open={open} onOpenChange={setOpen} role="status" alignment="bottomLeft" content={<span>Saved</span>}>
  <Button onClick={handleSave}>Save</Button>
</Popup>

const [scope, setScope] = useState('matters');

<Chip
  mode="scope"
  label="Matters"
  isSelected={scope === 'matters'}
  onSelectedChange={() => setScope('matters')}
/>

const [scopes, setScopes] = useState(() => new Set(['matters']));
const toggle = (id) =>
  setScopes((current) => {
    const next = new Set(current);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });

<ChipGroup size="sm" aria-label="Search scopes">
  {options.map((option) => (
    <Chip
      key={option.id}
      mode="scope"
      label={option.label}
      elemBefore={<SearchIcon decorative />}
      isSelected={scopes.has(option.id)}
      onSelectedChange={() => toggle(option.id)}
    />
  ))}
</ChipGroup>

function EditableTitle() {
  const [value, setValue] = useState('Q3 Planning');

  return (
    <InlineEdit value={value} onConfirm={setValue}>
      <TextField appearance="subtle" aria-label="Title" />
    </InlineEdit>
  );
}

const [open, setOpen] = useState(false);

<DropdownMenu
  aria-label="Matter actions"
  open={open}
  onOpenChange={setOpen}
  searchPlaceholder="Search actions"
  sections={[{
    id: 'actions',
    heading: 'Actions',
    items: [
      { id: 'rename', label: 'Rename', onSelect: () => { handleRename(); setOpen(false); } },
      { id: 'delete', label: 'Delete', onSelect: () => { handleDelete(); setOpen(false); } },
    ],
  }]}
>
  <Button onClick={() => setOpen((current) => !current)}>Actions</Button>
</DropdownMenu>

const [open, setOpen] = useState(false);

<DropdownMenu
  aria-label="Row actions"
  open={open}
  onOpenChange={setOpen}
  showSearch={false}
  sections={[{ id: 'actions', items: [{ id: 'archive', label: 'Archive', onSelect: () => setOpen(false) }] }]}
>
  <IconButton aria-label="Row actions" appearance="subtle" onClick={() => setOpen((current) => !current)}>
